cat > /srv/serve-static.pl <<'PERLEOF'
use strict; use warnings;
use IO::Socket::INET;
my $srv = IO::Socket::INET->new(LocalAddr=>'127.0.0.1', LocalPort=>8083,
                                Listen=>5, ReuseAddr=>1, Proto=>'tcp') or die "bind: $!";
my $pid = fork(); die "fork: $!" unless defined $pid;
if (!$pid) {
    for (1..10) {
        my $c = $srv->accept() or next;
        my $req = <$c> // '';
        while (defined(my $h = <$c>)) { last if $h =~ /^\r?\n$/ }
        my ($method, $path) = $req =~ m{^(\w+)\s+(\S+)};
        my $body = '';
        if (defined $path && open(my $f, '<', "/srv/static$path")) { local $/; $body = <$f>; close $f }
        print $c "HTTP/1.0 200 OK\r\nContent-Length: " . length($body) . "\r\n\r\n";
        print $c $body unless (defined $method && $method eq 'HEAD');
        close $c;
    }
    exit 0;
}
my $total = 0;
for my $i (1..5) {
    for my $method ('GET', 'HEAD') {
        my $c = IO::Socket::INET->new(PeerAddr=>'127.0.0.1', PeerPort=>8083, Proto=>'tcp')
            or die "connect: $!";
        print $c "$method /asset-$i.txt HTTP/1.0\r\n\r\n";
        my $len = 0;
        while (my $line = <$c>) { $line =~ s/\r?\n$//; last if $line eq '';
                                  $len = $1 if $line =~ /^Content-Length:\s*(\d+)/i }
        if ($method eq 'HEAD') { print "asset $i head length $len\n"; close $c; next }
        my $body = do { local $/; <$c> } // '';
        close $c;
        $total += length($body);
        open(my $f, '<', "/srv/static/asset-$i.txt") or die $!;
        my $disk = do { local $/; <$f> }; close $f;
        print "asset $i match ", ($body eq $disk ? 'True' : 'False'), "\n";
    }
}
waitpid($pid, 0);
close $srv;
print "bytes served $total\n";
PERLEOF
perl -c /srv/serve-static.pl
